.site-foot { background: #0065B3; color: #FFFFFF; font-family: 'Montserrat', sans-serif; font-weight: 300; }
.site-foot a { color: #FFFFFF; }
.ft-h2 { font-family: 'Fraunces Full', 'Fraunces', serif; font-weight: 700; font-optical-sizing: none; font-variation-settings: "opsz" 34, "WONK" 1; }
.ft-intro strong, .ft-b { font-weight: 700; }
.ft-rule { margin: 0; border: 0; border-top: 1px solid #FFFFFF; }
.ft-col h3 { font-family: 'Montserrat', sans-serif; font-weight: 700; }
.ft-legal ul { display: flex; flex-wrap: wrap; }
.ft-logo { height: auto; }
@media (min-width: 1024px) {
  .site-foot { height: calc(960 * var(--u, 1px)); }
  .ft-contact { position: absolute; left: calc(78 * var(--u, 1px)); top: calc(70 * var(--u, 1px)); width: calc(927 * var(--u, 1px)); }
  .ft-h2 { font-size: calc(34 * var(--u, 1px)); line-height: calc(50 * var(--u, 1px)); }
  .ft-hours { font-size: calc(20 * var(--u, 1px)); line-height: calc(30 * var(--u, 1px)); }
  .ft-reach { position: absolute; left: calc(79 * var(--u, 1px)); top: calc(221 * var(--u, 1px)); width: calc(1039 * var(--u, 1px)); font-size: calc(25 * var(--u, 1px)); line-height: calc(40 * var(--u, 1px)); }
  .ft-rule { position: absolute; left: calc(79 * var(--u, 1px)); top: calc(480 * var(--u, 1px)); width: calc(1279 * var(--u, 1px)); }
  .ft-menus { position: absolute; left: calc(78 * var(--u, 1px)); top: calc(531 * var(--u, 1px)); width: calc(1280 * var(--u, 1px)); display: grid; grid-template-columns: calc(375 * var(--u, 1px)) calc(341 * var(--u, 1px)) calc(287 * var(--u, 1px)) 1fr; }
  .ft-col h3 { font-size: calc(25 * var(--u, 1px)); line-height: calc(50 * var(--u, 1px)); }
  .ft-brand { position: absolute; left: calc(44 * var(--u, 1px)); top: calc(866 * var(--u, 1px)); display: flex; align-items: flex-start; }
  .ft-logo { width: calc(200 * var(--u, 1px)); }
  .ft-copy { margin: calc(24 * var(--u, 1px)) 0 0 calc(12 * var(--u, 1px)); font-size: calc(14 * var(--u, 1px)); line-height: calc(40 * var(--u, 1px)); }
  .ft-legal { position: absolute; left: calc(961 * var(--u, 1px)); top: calc(890 * var(--u, 1px)); font-size: calc(14 * var(--u, 1px)); line-height: calc(40 * var(--u, 1px)); }
  .ft-legal ul { gap: calc(29 * var(--u, 1px)); }
}
@media (max-width: 1023px) {
  .ft-h2 { font-size: 28px; line-height: 50px; }
  .ft-intro { font-size: 18px; line-height: 40px; }
  .ft-hours { font-size: 18px; line-height: 30px; }
  .ft-reach { font-size: 20px; line-height: 32px; letter-spacing: -0.035em; } /* Montserrat runs wider than Gotham */
  .ft-menus { display: grid; grid-template-columns: 187px 1fr; row-gap: 36px; }
  .ft-col h3 { font-size: 22px; line-height: 50px; }
  .ft-col ul { font-size: 16px; line-height: 40px; letter-spacing: -0.03em; }
  .ft-brand { display: flex; flex-direction: column; gap: 8px; }
  .ft-logo { width: 200px; }
  .ft-copy, .ft-legal { font-size: 12px; line-height: 14.4px; }
  .ft-legal ul { gap: 8px 22px; }
}
